    popup = floatingPopup(anchor, 'pb-action-menu');
  popup.dataset.align = 'end';
  popup.setAttribute('role', 'menu');
  popup.setAttribute('aria-label', label);
  anchor.setAttribute('aria-expanded', 'true');
