    const form = el(this.contentEl, 'form', 'pb-config-form');
    this.column = {
      value: crypto.randomUUID(),
      label: '',
      kind: 'active',
      color: '#a99bea',
      opacity: 0.06,
      icon: '',
    };
    const preview = el(form, 'div', 'pb-new-column-preview');
    const paint = () => {
      preview.style.background = tint(this.column.color, this.column.opacity);
    };
